-- Create table idempotently
CREATE TABLE IF NOT EXISTS historical_daily_sales (
    id UUID PRIMARY KEY,
    outlet_id UUID NOT NULL REFERENCES outlets(id),
    sales_date DATE NOT NULL,
    net_sales NUMERIC(10, 2) NOT NULL,
    transaction_count INTEGER NOT NULL,
    source VARCHAR(50) NOT NULL,
    source_ref VARCHAR(255) NOT NULL,
    created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uq_historical_daily_sales_outlet_date_source UNIQUE (outlet_id, sales_date, source),
    CONSTRAINT chk_historical_daily_sales_net_nonnegative CHECK (net_sales >= 0),
    CONSTRAINT chk_historical_daily_sales_txn_nonnegative CHECK (transaction_count >= 0)
);

CREATE INDEX IF NOT EXISTS ix_historical_daily_sales_outlet_date ON historical_daily_sales (outlet_id, sales_date);

ON CONFLICT (outlet_id, sales_date, source) DO NOTHING;


DO $$
DECLARE
    row_count INTEGER;
    net_sum NUMERIC(10, 2);
    txn_sum INTEGER;
    bedok_count INTEGER;
BEGIN
    SELECT COUNT(*), COALESCE(SUM(net_sales), 0), COALESCE(SUM(transaction_count), 0)
    INTO row_count, net_sum, txn_sum
    FROM historical_daily_sales
    WHERE source = 'qashier';

    IF row_count != 1178 THEN
        RAISE EXCEPTION 'Integrity check failed: Expected 1178 rows, got %', row_count;
    END IF;

    IF net_sum != 956371.38 THEN
        RAISE EXCEPTION 'Integrity check failed: Expected net_sales sum 956371.38, got %', net_sum;
    END IF;

    IF txn_sum != 65694 THEN
        RAISE EXCEPTION 'Integrity check failed: Expected transaction_count sum 65694, got %', txn_sum;
    END IF;

    SELECT COUNT(*) INTO bedok_count
    FROM historical_daily_sales h
    JOIN outlets o ON h.outlet_id = o.id
    WHERE o.name ILIKE '%Bedok%' AND h.source = 'qashier';

    IF bedok_count > 0 THEN
        RAISE EXCEPTION 'Integrity check failed: Found % Bedok rows', bedok_count;
    END IF;
END $$;
